INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l44','purse','handbag','手提包;美语 purse,英式 handbag(课文 handbag;注意英式 purse=钱包)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l44','cookie','biscuit','饼干;美语 cookie,英式 biscuit(野餐食物)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l44','candy','sweets','糖果;美语 candy,英式 sweets(野餐零食)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l44','sneakers','trainers','运动鞋;美语 sneakers,英式 trainers(追赶奔跑)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l44','start / keep + doing','',NULL,'/stɑːrt ˈduːɪŋ/','Both men started running through the trees.','两个男人开始在树林里奔跑。','She kept running even when out of breath.','即使喘不上气她也不停地跑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l44','so ... that','',NULL,'/soʊ ... ðæt/','She got so angry that she ran after them.','她气得追了上去。','The men got such a fright that they dropped the bag.','两个男人吓得扔下包。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l44','run after / catch up with','',NULL,'/rʌn ˈæftər/','She ran after the two men.','她追赶那两个男人。','When she caught up with them, they had sat down.','她追上他们时,他们已坐下。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l44','need + doing','',NULL,'/niːd ˈduːɪŋ/','The strap needs mending.','背带需要修理。','Your shoes need cleaning.','你的鞋需要擦了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp1','choice','{"stem":"\"___ is always a pleasure.\"(动词开头用 -ing)","options":["Ate","Eats","Eat","Eating"],"answer_index":3,"stem_cn":"吃东西总是一种享受。","explanation_cn":"动词作句子开头(当名词用)要用动名词 -ing。✓ Eating is always a pleasure 吃是一种享受。✗ Eat:动词原形不能作开头名词;✗ Ate / Eats:是谓语形式,不作开头名词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp1','choice','{"stem":"\"___ through the forest was dangerous.\"(动词开头用 -ing)","options":["Ran","Runs","Running","Run"],"answer_index":2,"stem_cn":"穿过森林奔跑很危险。","explanation_cn":"动词作句子开头用动名词 -ing。✓ Running through the forest was dangerous 奔跑穿林很危险。✗ Run:原形不作开头名词;✗ Ran / Runs:谓语形式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp2','choice','{"stem":"\"I am very keen on ___.\"(介词 on 后用动名词)","options":["cycling","cycled","cycle","to cycle"],"answer_index":0,"stem_cn":"我很热衷骑自行车。","explanation_cn":"介词(on)后面用动名词。✓ keen on cycling 热衷骑车。✗ cycle:原形;✗ to cycle:介词后不接不定式;✗ cycled:过去式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp2','choice','{"stem":"\"He sat there without ___ anything.\"(介词 without 后用动名词)","options":["said","saying","say","to say"],"answer_index":1,"stem_cn":"他坐在那儿一言不发。","explanation_cn":"介词(without)后面用动名词。✓ without saying anything 一言不发。✗ say:原形;✗ to say:介词后不接不定式;✗ said:过去式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp2','choice','{"stem":"\"I must apologize for ___ you know earlier.\"(介词 for 后用动名词)","options":["not let","not to let","not letting","didn''t let"],"answer_index":2,"stem_cn":"没早点告诉你,我得道歉。","explanation_cn":"介词(for)后用动名词,否定就在前面加 not。✓ apologize for not letting you know 没让你知道而道歉。✗ not let:缺 -ing;✗ not to let:介词后不接不定式;✗ didn''t let:不是动名词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp2','choice','{"stem":"\"She is good at ___ pictures.\"(介词 at 后用动名词)","options":["drawing","to draw","draw","drew"],"answer_index":0,"stem_cn":"她擅长画画。","explanation_cn":"介词(at)后面用动名词。✓ good at drawing 擅长画画。✗ draw:原形;✗ to draw:介词后不接不定式;✗ drew:过去式。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp3','choice','{"stem":"\"They enjoy ___ in the forest.\"(enjoy 后只能接动名词)","options":["have picnics","had picnics","to have picnics","having picnics"],"answer_index":3,"stem_cn":"他们喜欢在森林里野餐。","explanation_cn":"enjoy 后面只能接动名词。✓ enjoy having picnics 喜欢野餐。✗ have picnics:缺 -ing;✗ to have picnics:enjoy 后不接不定式;✗ had picnics:过去式。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp3','choice','{"stem":"\"She kept ___ even when out of breath.\"(keep 后接动名词)","options":["running","ran","to run","run"],"answer_index":0,"stem_cn":"即使喘不上气她仍不停地跑。","explanation_cn":"keep 后面接动名词表\"不停地做\"。✓ kept running 不停地跑。✗ run:缺 -ing;✗ to run:keep 后不接不定式;✗ ran:过去式。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp3','choice','{"stem":"\"Would you mind ___ the window?\"(mind 后只能接动名词)","options":["to close","closed","close","closing"],"answer_index":3,"stem_cn":"你介意关一下窗户吗?","explanation_cn":"mind 后面只能接动名词。✓ Would you mind closing…? 你介意关…吗?✗ close:缺 -ing;✗ to close:mind 后不接不定式;✗ closed:过去式。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp4','choice','{"stem":"\"Thank you for ___ me wait long.\"(动名词否定:没…)","options":["not to keep","not keeping","not keep","not kept"],"answer_index":1,"stem_cn":"谢谢你没让我久等。","explanation_cn":"介词(for)后用动名词,否定加 not。✓ Thank you for not keeping me wait 谢谢你没让我等。✗ not keep:缺 -ing;✗ not to keep:介词后不接不定式;✗ not kept:不是动名词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp4','choice','{"stem":"\"She apologized for ___ the letter.\"(动名词否定:没…)","options":["not answered","not to answer","not answering","not answer"],"answer_index":2,"stem_cn":"她为没回信道歉。","explanation_cn":"介词(for)后用动名词,否定加 not。✓ apologized for not answering the letter 为没回信道歉。✗ not answer:缺 -ing;✗ not to answer:介词后不接不定式;✗ not answered:不是动名词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp5','choice','{"stem":"\"Mrs. Sterling got ___ angry that she ran after them.\"(…得…以至于,后接形容词)","options":["so","too","very","such"],"answer_index":0,"stem_cn":"斯特林夫人气得追了上去。","explanation_cn":"\"…得…以至于\",后接形容词用 so + adj + that。✓ so angry that… 气得…。✗ such:后接名词;✗ very:不与 that 构成因果;✗ too:是\"太…(而不能)\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp5','choice','{"stem":"\"The men got ___ a fright that they dropped the bag.\"(…得…以至于,后接 a+名词)","options":["so","such","very","too"],"answer_index":1,"stem_cn":"两个男人吓得扔下包就跑。","explanation_cn":"\"…得…以至于\",后接\"a + 名词\"用 such + a + n + that。✓ such a fright that… 吓得…。✗ so:后接形容词/副词;✗ very / too:不与 that 构成此结构。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp6','choice','{"stem":"\"The strap needs ___.\"(need + 动名词,表''需要被…'')","options":["mended","to mend","mend","mending"],"answer_index":3,"stem_cn":"背带需要修理。","explanation_cn":"need + 动名词,表\"需要被…\"(被动含义)。✓ The strap needs mending 背带需要修理。✗ to mend:此处用动名词表被动;✗ mend:缺形式;✗ mended:不接过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp6','choice','{"stem":"\"Your shoes need ___.\"(need + 动名词,表''需要被…'')","options":["cleaned","cleaning","clean","to clean"],"answer_index":1,"stem_cn":"你的鞋需要擦了。","explanation_cn":"need + 动名词,表\"需要被…\"。✓ Your shoes need cleaning 你的鞋需要擦。✗ to clean:此处用动名词;✗ clean:缺形式;✗ cleaned:不接过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp7','choice','{"stem":"\"She ran ___ the two men who took her bag.\"(追赶)","options":["into","over","for","after"],"answer_index":3,"stem_cn":"她追赶那两个抢包的男人。","explanation_cn":"run after 表\"追赶\"。✓ ran after the two men 追那两个男人。✗ for:run for 是\"竞选/跑向\";✗ into:run into 是\"遇到\";✗ over:run over 是\"碾过\"。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp7','choice','{"stem":"\"When she caught ___ with them, they had sat down.\"(赶上,追上)","options":["on","up","out","off"],"answer_index":1,"stem_cn":"当她追上他们时,他们已坐下。","explanation_cn":"catch up with 表\"赶上、追上\"。✓ caught up with them 追上他们。✗ on:catch on 是\"流行/听懂\";✗ off / out:不与 catch…with 搭配这个意思。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',5,'am2_l44_gp8','choice','{"stem":"\"She was soon ___ of breath but kept running.\"(喘不上气)","options":["without","short","out","lack"],"answer_index":2,"stem_cn":"她很快喘不上气,却仍不停地跑。","explanation_cn":"out of breath 表\"上气不接下气\"。✓ out of breath 喘不上气。✗ without / short / lack:不与 of breath 构成这个固定短语。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"美语里\"(女式)手提包\"常说:","options":["carry bag","handbag","purse","hand sack"],"answer_index":2,"explanation_cn":"美语\"(女式)手提包\"常说 purse;英式说 handbag(英式 purse 指钱包)。✓ carry a purse 拎着手提包。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"美语里\"饼干\"常说:","options":["biscuit","sweet cake","cracker cake","cookie"],"answer_index":3,"explanation_cn":"美语\"饼干\"常说 cookie;英式说 biscuit。✓ eat a cookie 吃饼干。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"forest 的意思是:","options":["草原","沙漠","森林","山谷"],"answer_index":2,"explanation_cn":"forest = 森林。✓ ran through a forest 穿过森林。\n顺带记:沙漠 = desert;草原 = grassland;山谷 = valley."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"risk 的意思是:","options":["危险,冒险","机会","幸运","安全"],"answer_index":0,"explanation_cn":"risk = 危险、冒险。✓ the risk she was taking 她所冒的风险。\n顺带记:安全 = safety;机会 = chance;幸运 = luck."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"breath 的意思是:","options":["风","声音","气味","呼吸"],"answer_index":3,"explanation_cn":"breath = 呼吸。✓ out of breath 喘不上气。\n顺带记:气味 = smell;声音 = sound;风 = wind."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',6,NULL,'choice','{"stem":"mend 的意思是:","options":["购买","修理","丢弃","弄坏"],"answer_index":1,"explanation_cn":"mend = 修理。✓ The strap needs mending 带子需要修理。\n顺带记:弄坏 = break;丢弃 = throw away;购买 = buy."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',7,NULL,'cloze','{"stem":"第 1 空","context":"While Mrs. Sterling was ___1___ a picnic, two men stole her bag and started ___2___ away. She was soon out of breath, but she kept ___3___. ___4___ after thieves through a forest was a real risk!","blank_no":1,"options":["having","have","to have","had"],"answer_index":0,"explanation_cn":"be having a picnic 现在进行,have + -ing。✓ she was having a picnic 她正在野餐。\n✗ have:缺 -ing;✗ to have / had:不合 was + -ing。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',7,NULL,'cloze','{"stem":"第 2 空","context":"While Mrs. Sterling was ___1___ a picnic, two men stole her bag and started ___2___ away. She was soon out of breath, but she kept ___3___. ___4___ after thieves through a forest was a real risk!","blank_no":2,"options":["running","run","to run","ran"],"answer_index":0,"explanation_cn":"start 后接动名词。✓ started running away 开始跑开。\n✗ run:缺 -ing;✗ to run:此处用动名词;✗ ran:过去式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',7,NULL,'cloze','{"stem":"第 3 空","context":"While Mrs. Sterling was ___1___ a picnic, two men stole her bag and started ___2___ away. She was soon out of breath, but she kept ___3___. ___4___ after thieves through a forest was a real risk!","blank_no":3,"options":["going","go","to go","went"],"answer_index":0,"explanation_cn":"keep 后接动名词表\"不停地\"。✓ she kept going 她不停地跑。\n✗ go:缺 -ing;✗ to go:keep 后不接不定式;✗ went:过去式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',7,NULL,'cloze','{"stem":"第 4 空","context":"While Mrs. Sterling was ___1___ a picnic, two men stole her bag and started ___2___ away. She was soon out of breath, but she kept ___3___. ___4___ after thieves through a forest was a real risk!","blank_no":4,"options":["Running","Run","To run","Ran"],"answer_index":0,"explanation_cn":"动词作句子开头(当名词用)要用动名词 -ing。✓ Running after thieves was a risk 追贼很冒险。\n✗ Run:原形不作开头名词;✗ To run:此处用动名词更自然;✗ Ran:谓语形式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',8,NULL,'choice','{"stem":"What were Mrs. Sterling and her children doing at the edge of the forest?","options":["Having a picnic","Picking flowers","Riding bikes","Camping overnight"],"answer_index":0,"explanation_cn":"课文说 she was having a picnic at the edge of a forest with her children,她和孩子们在林边野餐。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',8,NULL,'choice','{"stem":"What did the two men try to steal?","options":["Her car","Her food basket","Her camera","Her handbag"],"answer_index":3,"explanation_cn":"课文说 tried to steal her handbag,他们企图抢她的手提包。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',8,NULL,'choice','{"stem":"How did the men react when Mrs. Sterling ran straight at them?","options":["They called the police","They gave the bag back politely","They got such a fright that they dropped the bag and ran away","They pushed her over"],"answer_index":2,"explanation_cn":"课文说 The men got such a fright that they dropped the bag and ran away,他们吓得扔包逃跑。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',9,NULL,'choice','{"stem":"你想说\"吃东西总是一种享受\"(动名词作句子开头用 -ing):","options":["To eating is always a pleasure.","Eaten is always a pleasure.","Eating is always a pleasure.","Eat is always a pleasure."],"answer_index":2,"explanation_cn":"动词作句子开头当名词用,要用动名词 -ing。✓ Eating is always a pleasure. 场合:说做某事(泛指)是怎样的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',9,NULL,'choice','{"stem":"你想说\"背带需要修理\"(need + 动名词表''需要被…''):","options":["The strap need mending.","The strap needs mend.","The strap needs to mending.","The strap needs mending."],"answer_index":3,"explanation_cn":"need + 动名词表\"需要被…\"(被动含义)。✓ The strap needs mending. 场合:说某物需要(被)修理/处理。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',9,NULL,'choice','{"stem":"你想说\"她气得追了上去\"(so + 形容词 + that):","options":["She got so angry that she ran after them.","She got such angry that she ran after them.","She got so angry that she ran after they.","She got angry so that she ran after them."],"answer_index":0,"explanation_cn":"\"…得…以至于\",后接形容词用 so + adj + that。✓ She got so angry that she ran after them. 场合:说因为太怎样而做了某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"forest 的意思是:","options":["城市","森林","沙漠","海洋"],"answer_index":1,"explanation_cn":"forest = 森林。✓ through a forest 穿过森林。\n顺带记:沙漠 = desert;海洋 = ocean;城市 = city."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"mend 的意思是:","options":["修理","丢弃","弄坏","购买"],"answer_index":0,"explanation_cn":"mend = 修理。✓ needs mending 需要修理。\n顺带记:弄坏 = break;购买 = buy;丢弃 = throw away."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"\"Both men started ___ through the trees.\"(动词后接动名词)","options":["to run","running","run","ran"],"answer_index":1,"stem_cn":"两个男人开始在树林里奔跑。","explanation_cn":"start 后接动名词。✓ started running through the trees 开始在树林里跑。\n✗ run:缺 -ing;✗ to run:此处用动名词;✗ ran:过去式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"\"The strap needs ___.\"(need + 动名词,表''需要被…'')","options":["mending","to mend","mended","mend"],"answer_index":0,"stem_cn":"背带需要修理。","explanation_cn":"need + 动名词,表\"需要被…\"(被动含义)。✓ The strap needs mending 背带需要修理。\n✗ to mend:此处用动名词;✗ mend:缺形式;✗ mended:不接过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"\"Mrs. Sterling got so angry that she ran after them.\" 这句话的意思是:","options":["斯特林夫人不敢追他们。","斯特林夫人气得追了上去。","斯特林夫人请他们停下。","斯特林夫人生气地走开了。"],"answer_index":1,"explanation_cn":"Mrs. Sterling got so angry that she ran after them. so…that = \"如此…以至于\",意思是\"斯特林夫人气得追了上去\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"\"The men got such a fright that they dropped the bag.\" 这句话的意思是:","options":["两个男人把包还了回来。","两个男人藏起了包。","两个男人抢到了包。","两个男人吓得扔下包(就跑)。"],"answer_index":3,"explanation_cn":"The men got such a fright that they dropped the bag. such…that = \"如此…以至于\",意思是\"两个男人吓得扔下包(就跑)\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"Why did Mrs. Sterling run after the two men?","options":["She was lost in the forest","She wanted to give them food","They had grabbed her handbag and run off with it","They were her children"],"answer_index":2,"passage":"Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men. They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag. In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees. Mrs. Sterling got so angry that she ran after them. She was soon out of breath, but she continued to run. When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them. The men got such a fright that they dropped the bag and ran away. ''The strap needs mending,'' said Mrs. Sterling later, ''but they did not steal anything.''","explanation_cn":"课文说两个男人抢了她的手提包跑进树林,她才追上去。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"What were the men doing when Mrs. Sterling caught up with them?","options":["Sitting down and going through the contents of the bag","Eating a picnic","Fixing the strap","Climbing a tree"],"answer_index":0,"passage":"Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men. They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag. In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees. Mrs. Sterling got so angry that she ran after them. She was soon out of breath, but she continued to run. When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them. The men got such a fright that they dropped the bag and ran away. ''The strap needs mending,'' said Mrs. Sterling later, ''but they did not steal anything.''","explanation_cn":"课文说 they had sat down and were going through the contents of the bag,他们坐着翻看包里东西。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"Did the men manage to steal anything in the end?","options":["Yes — they took all her money","Yes — they kept the handbag","No — the police caught them","No — they dropped the bag and ran away"],"answer_index":3,"audio":"Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men. They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag. In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees. Mrs. Sterling got so angry that she ran after them. She was soon out of breath, but she continued to run. When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them. The men got such a fright that they dropped the bag and ran away. ''The strap needs mending,'' said Mrs. Sterling later, ''but they did not steal anything.''","explanation_cn":"课文说他们吓得扔下包逃跑,夫人还说 they did not steal anything,什么也没偷走。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l44',10,NULL,'choice','{"stem":"What did Mrs. Sterling say afterward about the strap?","options":["It needed mending, but nothing was stolen","It was brand new","It was made of leather","The men had fixed it"],"answer_index":0,"audio":"Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men. They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag. In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees. Mrs. Sterling got so angry that she ran after them. She was soon out of breath, but she continued to run. When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them. The men got such a fright that they dropped the bag and ran away. ''The strap needs mending,'' said Mrs. Sterling later, ''but they did not steal anything.''","explanation_cn":"课文结尾夫人说 The strap needs mending, but they did not steal anything。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
